L000030	\title{Dynamics of density fluctuations in atomic nuclei}
L000031	
L000032	\author{Francesca~Bonaiti\orcidlink{0000-0002-3926-1609}}
L000033	\email{bonaiti@frib.msu.edu}
L000034	\affiliation{Facility for Rare Isotope Beams, Michigan State University, East Lansing, Michigan 48824, USA}
L000035	\affiliation{Physics Division, Oak Ridge National Laboratory, Oak Ridge, Tennessee 37831, USA}
L000036	
L000037	\author{Gaute~Hagen\orcidlink{0000-0001-6019-1687}}
L000038	\affiliation{Physics Division, Oak Ridge National Laboratory, Oak Ridge, Tennessee 37831, USA}
